import pathlib
from typing import Optional, Literal, Union, TypedDict, Unpack

import requests

from pyvkteamsclient.client.utils import read_in_chunks
from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.tracer import tracer


class FilesInitKwargs(TypedDict):
    send_to: str
    r: str
    type: str
    duration: int
    language: Literal["ru_RU", "eu_EU"]
    is_sticker: int
    is_avatar: int


class FilesPreviewTtl(TypedDict):
    dlink: int
    accept: str


class FilesCrashList(TypedDict):
    limit: str
    start_after: int
    date: str


class FilesLottieOriginal(TypedDict):
    source: str
    accept: str


class FilesStickerGet(TypedDict):
    source: str
    range: str
    accept: str


class FilesMethods(BaseClient):
    """
    Методы группы 'Файлы' из https://im-docs.corp.mail.ru/
    """

    @tracer.start_as_current_span("files.files_init")
    def files_init(self, filename: str, size: int, **kwargs: Unpack[FilesInitKwargs]) -> dict:
        r"""
        API выполняется перед закачкой файла.
        Вызов API нужен для того, чтобы определить сервер,
        на который будет происходить закачка,
        чтобы все чанки попали на один сервер.
        Если ответ успешный, то дальнейшая закачка происходит на сервер,
        указанный в поле data[url]"

        В данный момент ограничение на закачку - 2Гб
        Для загрузки chunk - ограничение 16Мб
        :param filename: Имя загружаемого файла
        :param size: Размер загружаемого файла в байтах
        param type: Тип загружаемого контента Допустимые типы:
        type=ptt - загрузка видео или аудио контента для распознавания текста речи.
        Для ptt меняетя символ типа в fileID. \n
        param send_to: Существует возможность отправить сообщение со ссылкой на загруженный файл, чрез параметры
        send_to, r, aimsid и k (aces) массив получателей ссылки на файл send_to=[111,222,3333] \n
        param r: уникальные идентификаторы сообщений r=[a1,b2,c3]
        """
        return self.get(
            "files/init/",
            aimsid=self.aimsid,
            f="json",
            k=self.token,
            r=self.getReqId(),
            filename=filename,
            size=size,
            language="ru_RU",
            client="VK Teams Mac OS",
            **kwargs,
        )

    @tracer.start_as_current_span("files.files_info")
    def files_info(
        self,
        file_id: str,
        preview: list[str] = (),
        previews: list[str] = (),
        source: Optional[str] = None,
        ptt_text: int = 0,
        support_webp: int = 0,
    ) -> dict:
        """
        Данный метод возвращает информацию о файле.
        Такую, как ссылки на превью, мета-информация и т.д.
        :param file_id: уникальный file_id хэш файла,
        например 28g8gk2L0MDQ2vndaxW9r45a326ee91ab
        :param preview: Превью, которые необходимы в ответе
        :param previews: Список (через запятую) названий превью,
        которые необходимы в ответе
        :param source:
        :param ptt_text: Добавить в ответ текст
        распознанного голосового сообщения
        :param support_webp: Если параметр выставлен в 1,
        то клиент поддерживает webp.
        Если клиент поддерживает webp и запросил info по неанимированному
        стикеру или webp-изображению,
        то в ответ получит mime: image/webp и размер оригинала в формате webp;
        Если клиент не поддерживает webp,
        но запрашивает info о webp-изображении,
        то в ответ он получит mime: image/png и размер оригинала в формате png;
        Для всех остальных случаев info возвращает mime
        и размер файла без преобразований.
        :return: тело ответа сервера
        """
        return self.get(
            f"files/info/{file_id}",
            aimsid=self.aimsid,
            preview=preview,
            previews=",".join(previews),
            source=source,
            ptt_text=ptt_text,
            support_webp=support_webp,
        )

