    @tracer.start_as_current_span("files.files_preview_ttl")
    def files_preview_ttl(self, size, ttl_hash, **kwargs: Unpack[FilesPreviewTtl]):
        r"""
        получить предварительный просмотр указанного размера по временному хэшу
        :param size: Available values : 192, 194, 600, 800, small, medium, large, xlarge, iphone, iphone_retina, mdpi,
        hdpi, xhdpi, xxhdpi, 400, share, review_large, preview_medium, preview_small, listicon_large, listicon_medium,
        listicon_small, sticker_xxlarge, sticker_xlarge, sticker_large, sticker_medium, sticker_small, icon_large,
        icon_medium, icon_small, stickerpicker_large, stickerpicker_medium, stickerpicker_small, stickerpicker_xsmall
        :param ttl_hash: уникальный подписанный и зашифрованный хэш, сгенерированный /info для всех ссылок, по
        которым он отвечает. Это часть всех ссылок, которые у вас там есть
        param dlink: Если в запросе есть параметр dlink=1, тогда ответ возвращает http-заголовок Original-D link -
        ссылка для загрузки оригинала \n
        param Accept: В том случае, если в заголовке содержится Mime image/webp сервис предпримет попытку нарезать
        изображение в формате webp Если клиент запрашивает превью для изображения webp без заголовка Accept,
        содержащего image/webp, он получит превью в формате image/png Example : image/* image/webp \n
        """
        return self.request(
            method="GET",
            url=f"{self.binary_api_url}/files/preview/ttl/{size}/{ttl_hash}",
            params={"aimsid": self.aimsid, **kwargs},
        )

