    @tracer.start_as_current_span("files.files_crash_list")
    def files_crash_list(self, platform: Literal["desktop", "ios", "android"], **kwargs: Unpack[FilesCrashList]):
        """
        Список загруженных крэшей
        :param platform: Имя платформы: ios, android, desktop
        param limit: Макимальное значение: 1000
        param start_after: Параметр используется для пагинации. В качестве аргумента принимает имя файла от которого
        будут отображены следующие результаты.
        param date: Параметр используется для отображения отчетов за указанную дату.
        """
