    @tracer.start_as_current_span("files.files_crash_download")
    def files_crash_download(self, file_name, platform: str = "desktop") -> requests.Response:
        response = self.session.get(
            "/".join([self.base_url, f"files/crash/download/{platform}/"]),
            params={"aimsid": self.aimsid, "name": file_name},
        )
        response.encoding = "utf-8"

        self.allure_attach(response)

        return response

