    @tracer.start_as_current_span("files.files_textforspeech")
    def files_textforspeech(self, file_id: str, text: str, language: str = "ru_RU") -> dict:
        """
        Метод позволяет привязать распознанный средствами ОС текст к PTT файлу.

        Если файл был распознан ранее, либо текст уже был привязан,
        то он не перезаписывается.
        """
        return self.post(
            f"files/textforspeech/{file_id}/{language}/",
            params={"aimsid": self.aimsid, "text": text},
        )

    @tracer.start_as_current_span("files.files_direct_upload")
    def files_direct_upload(
        self,
        chat_id: str,
        file_path: Union[str, pathlib.Path],
        type_format: Optional[str] = "ptt",
        language: Optional[str] = "ru_RU",
        is_sticker: Optional[int] = 0,
        is_avatar: Optional[int] = 0,
        chunk_size: int = 1024 * 8,
    ):
        r"""
        Выбор сервера для загрузки + загрузка первого чанка файла
        Позволяет загружать в один чанк или загружать первый чанк и получить upload host для дальнейшей загрузки файла.
        Параметры точно такие же как и в /upload/init, но в теле запроса первый чанк или файл целиком, если размер
        позволяет. Если фаил был загружен целиком, то будет ответ 200 и результат как от успешного аплоада.
        Если требуется загрузить больше чанков, то будет ответ 206 и результат ответа как в выборе аплоад сервера
        :param filename: имя загружаемого файла
        :param size: размер загружаемого файла в байтах
        :param client: название клиента (icq или agent)
        param send_to: Существует возможность отправить сообщение со ссылкой на загруженный файл, чрез параметры
        send_to, r, aimsid и k (aces) массив получателей ссылки на файл send_to=[111,222,3333] \n
        :param type: Тип загружаемого контента Допустимые типы: type=ptt - загрузка видео или аудио контента для
        распознавания текста речи. Для ptt меняетя символ типа в fileID. Допустимые форматы: m4a, aac \n
        param duration: Продолжительность записи в секундах. По умолчанию 0. Обязательный для type=ptt
        Продолжительность не вычисляется на сервере! \n
        :param language: Язык записываемого аудио. Обязателен при загрузке с type=ptt. Доступные языки для
        распознавания: ru_RU \n
        :param is_sticker: is_sticker=1 - загрузить картинку как стикер
        :param is_avatar: s_avatar=1 - загрузить картинку как как аватар Дополнительно нарежутся 3 размера квадратных
        с crop'ом по большей стороне: buddyicon_small(64px) buddyicon_medium(128px) buddyicon_large(1024px) \n
        """
        file_size = file_path.stat().st_size
        file_name = file_path.name

        if chunk_size <= 0 or file_size <= chunk_size:
            chunk_size = file_size

            return self.request(
                method="POST",
                url=f"{self.binary_api_url}/files/direct_upload/",
                headers={"Content-Range": f"bytes 0-{chunk_size - 1}/{file_size}"},
                params={
                    "filename": file_name,
                    "size": file_size,
                    "client": "VK Teams",
                    "send_to": chat_id,
                    "r": self.getReqId(),
                    "type": type_format,
                    "language": language,
                    "is_sticker": is_sticker,
                    "is_avatar": is_avatar,
                    "aimsid": self.aimsid,
                },
                data=file_path.read_bytes(),
            )

        full_chunks_count = file_size // chunk_size

        last_chunk_size = file_size - chunk_size * full_chunks_count

        for i, chunk in enumerate(read_in_chunks(file_path.absolute(), blocksize=chunk_size)):
            if i == 0:
                result = self.request(
                    method="POST",
                    url=f"{self.binary_api_url}/files/direct_upload/",
                    headers={"Content-Range": f"bytes {i * chunk_size}-{(i + 1) * chunk_size - 1}/{file_size}"},
                    params={
                        "filename": file_name,
                        "size": file_size,
                        "client": "VK Teams",
                        "send_to": chat_id,
                        "r": self.getReqId(),
                        "type": type_format,
                        "language": language,
                        "is_sticker": is_sticker,
                        "is_avatar": is_avatar,
                        "aimsid": self.aimsid,
                    },
                    data=chunk,
                )
            elif i < full_chunks_count:
                content_range = f"bytes {i * chunk_size}-{(i + 1) * chunk_size - 1}/{file_size}"

                self.request(
                    method="POST",
                    url="https://{host}{url}".format(**result["result"]),
                    headers={"Content-Range": content_range},
                    params={
                        "aimsid": self.aimsid,
                        "f": "json",
                        "k": self.devId,
                        "size": file_size,
                        "filename": file_name,
                        "name": file_name,
                        "client": "myteam",
                    },
                    data=chunk,
                )
            else:
                content_range = (
                    f"bytes "
                    f"{full_chunks_count * chunk_size}"
                    f"-"
                    f"{full_chunks_count * chunk_size + last_chunk_size - 1}"
                    f"/"
                    f"{file_size}"
                )
                return self.request(
                    method="POST",
                    url="https://{host}{complete_url}".format(**result["result"]),
                    headers={"Content-Range": content_range},
                    params={
                        "aimsid": self.aimsid,
                        "f": "json",
                        "k": self.devId,
                        "size": file_size,
                        "client": "myteam",
                    },
                    data=chunk,
                )

    @tracer.start_as_current_span("files.files_lottie_original")
    def files_lottie_original(self, file_id: str, **kwargs: Unpack[FilesLottieOriginal]) -> dict:
        r"""
        Скачмвать стикер по file_id
        Позволяет скачать содержимое стикера по file_id без механизма dlink, работает только для файлов-стикеров
        :param file_id: image file_id hash, example 0kEgwIGt9y6eV3jRkH8rjY5cd277c51ab
        param source: Идентификатор федерации источника файла. Берётся из ссылки на файл
        (например, https://files.icq.com/get/29Xak000pQJ71N5GWfOIGT601364e31aj?source=onpremise2_feddaemon) \n
        param Accept: В том случае, если в заголовке содержится Mime image/webp и файл является неанимированным
        стикером сервис попытается отдать в ответе оригинал в формате webp, в случае неудачи преобразования к формату
        webp в ответ отправляется файл в том формате, в котором был загружен (например png) Если клиент запрашивает
        оригинал для изображения webp без заголовка Accept, содержащего image/webp, он получит оригинал файла в формате
        image/png Example : image/* image/webp \n
        :return: тело ответа сервера
        """
        return self.request(
            method="GET",
            url=f"{self.binary_api_url}/files/lottie_original/{file_id}/",
            params={"aimsid": self.aimsid, **kwargs},
        )

    @tracer.start_as_current_span("files.files_sticker_get")
    def files_sticker_get(self, file_id: str, **kwargs: Unpack[FilesStickerGet]) -> dict:
        r"""
        Скачмвать стикер по file_id
        Позволяет скачать содержимое стикера по file_id без механизма dlink, работает только для файлов-стикеров
        :param file_id: file_id для стикера
        param source: Идентификатор федерации источника файла. Берётся из ссылки на файл
        (например, https://files.icq.com/get/29Xak000pQJ71N5GWfOIGT601364e31aj?source=onpremise2_feddaemon) \n
        param Range: Позволяет скачать файл частями, через смещение и лимит в заголовке Example : bytes=0-1023 \n
        param Accept: В том случае, если в заголовке содержится Mime image/webp и файл является неанимированным
        стикером сервис попытается отдать в ответе оригинал в формате webp, в случае неудачи преобразования к формату
        webp в ответ отправляется файл в том формате, в котором был загружен (например png) Если клиент запрашивает
        оригинал для изображения webp без заголовка Accept, содержащего image/webp, он получит оригинал файла в формате
        image/png Example : image/* image/webp \n
        :return: тело ответа сервера
        """
        return self.request(
            method="GET",
            url=f"{self.binary_api_url}/files/sticker/{file_id}",
            params={"aimsid": self.aimsid, **kwargs},
        )
